design.css:
.section-view-folder-pane .folder-row { border-radius: 0; }
.note-status-bar {
  gap: 12px;
  padding: 3px 12px;
  border: 1px solid #24743a;
  border-top-color: #43a35b;
  border-radius: 3px;
  color: #e5f4d0;
  background: linear-gradient(180deg, #16381b, #0b180e);
  box-shadow: inset 0 0 0 2px #0b180e, 0 3px 12px #00000040;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 600;
  font-variant-numeric: lining-nums tabular-nums;
  letter-spacing: 0.025em;
}
.ProseMirror::selection, .ProseMirror *::selection, .note-title-input::selection, .raw-markdown-input::selection {
  background: #28753c;
  color: #ffffff;
}

